import React, { useState } from "react";
import styled from "styled-components";
import { useNotice } from "../context/NoticeContext";
import FileViewer from "./FileViewer";
import { Eye, EyeOff, Download, X } from "lucide-react";

const DimBackground = styled.div`
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.4);
  z-index: 999;
`;

const PopupOverlay = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-height: 90vh;
  background: white;
  z-index: 1000;
  padding: 24px;
  overflow-y: auto;
  border-radius: 12px;
`;

const PopupHeader = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const CloseButton = styled.button`
  background: none;
  border: none;
  cursor: pointer;
`;

const SectionRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
`;

const ActionButtons = styled.div`
  display: flex;
  gap: 8px;
`;

const DatasetPopup = ({ genome, onClose }) => {
  const [visibleSections, setVisibleSections] = useState({
    amr: false,
    virulence: false,
    resistance: false,
  });

  const toggleSection = (key) => {
    setVisibleSections({ ...visibleSections, [key]: !visibleSections[key] });
  };

  return (
    <>
      <DimBackground onClick={onClose} />
      <PopupOverlay>
        <PopupHeader>
          <CloseButton onClick={onClose}>
            <X />
          </CloseButton>
        </PopupHeader>
        <h2
          style={{
            fontSize: "1.25rem",
            fontWeight: "bold",
            marginBottom: "1rem",
          }}
        >
          {genome.name} - {genome.genomeId}
        </h2>

        <div>
          <SectionRow>
            <span>contig.fasta</span>
            <CloseButton>
              <Download />
            </CloseButton>
          </SectionRow>

          <SectionRow>
            <span>AMR Genes</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("amr")}>
                {visibleSections.amr ? <EyeOff /> : <Eye />}
              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <SectionRow>
            <span>Virulences</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("virulence")}>
              <span>{visibleSections.amr ? "🧐" : "🔍"}</span>

              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <SectionRow>
            <span>Kháng sinh (CSV)</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("resistance")}>
                {visibleSections.resistance ? <EyeOff /> : <Eye />}
              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <div style={{ marginTop: "24px" }}>
            {visibleSections.amr && <FileViewer content={genome.amr} />}
            {visibleSections.virulence && (
              <FileViewer content={genome.virulence} />
            )}
            {visibleSections.resistance && (
              <FileViewer content={genome.resistance} />
            )}
          </div>
        </div>
      </PopupOverlay>
    </>
  );
};

export default DatasetPopup;
